
.mirror-panel {
  --m-accent: #c9a96e;
  --m-accent-dim: rgba(201, 169, 110, 0.2);
  --m-glow: rgba(201, 169, 110, 0.1);
  --m-surface: #f5ede0;
  --m-text: #4a4035;
  --m-muted: #8a7e6e;
  --m-dim: #b8a898;
  --m-rose: #c47b8b;
  --m-rose-dim: rgba(196, 123, 139, 0.2);
  --m-teal: #5ea0a7;
  --m-teal-dim: rgba(94, 160, 167, 0.18);
  padding: 4px 0 6px;
  &.theme-red {
    --m-accent: var(--m-rose);
    --m-accent-dim: var(--m-rose-dim);
    --m-surface: #251c1f;
    --m-text: #e0d0d8;
    --m-muted: #b098a0;
    --m-dim: #786068;
  }
  &.theme-teal {
    --m-accent: var(--m-teal);
    --m-accent-dim: var(--m-teal-dim);
    --m-surface: #1c2325;
    --m-text: #d0dce0;
    --m-muted: #98a8b0;
    --m-dim: #607078;
  }
}
.mirror-frame {
  position: relative;
  border-radius: 12px;
  padding: 4px;
  background: linear-gradient(145deg, #8b7355, #6b5a48 25%, #c9a96e 50%, #6b5a48 75%, #8b7355);
  box-shadow: 0 0 24px rgba(201, 169, 110, 0.15);
}
.frame-ring,
.frame-inset {
  position: absolute;
  border-radius: 10px;
  border: 1px solid rgba(201, 169, 110, 0.25);
  pointer-events: none;
}
.frame-ring {
  inset: 4px;
}
.frame-inset {
  inset: 8px;
  border-color: rgba(201, 169, 110, 0.1);
}
.mirror-surface {
  position: relative;
  z-index: 1;
  border-radius: 9px;
  padding: 14px 12px 10px;
  background: var(--m-surface);
  overflow: hidden;
  &::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: 0;
    pointer-events: none;
    background-image:
      repeating-linear-gradient(45deg, transparent, transparent 2px, var(--m-accent) 2px, var(--m-accent) 3px),
      repeating-linear-gradient(-45deg, transparent, transparent 2px, var(--m-accent) 2px, var(--m-accent) 3px);
    opacity: 0.04;
  }
}
.panel-title {
  font-family: '寒蝉全圆体', var(--font-main);
  text-align: center;
  font-size: 18px;
  font-weight: 700;
  letter-spacing: 6px;
  position: relative;
  z-index: 1;
  background: linear-gradient(135deg, #6b4a28 0%, #8b5a30 40%, #6b4a28 60%, #8b5a30 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}
.panel-sub {
  font-family: '寒蝉全圆体', var(--font-main);
  text-align: center;
  font-size: 9px;
  color: var(--m-accent);
  letter-spacing: 2px;
  margin-bottom: 8px;
  position: relative;
  z-index: 1;
}
.mirror-tabs {
  display: flex;
  justify-content: center;
  gap: 0;
  margin-bottom: 8px;
  position: relative;
  z-index: 1;
  button {
    font-family: '寒蝉全圆体', var(--font-main);
    font-size: 10px;
    padding: 3px 12px;
    border: 1px solid var(--m-accent-dim);
    background: transparent;
    color: var(--m-muted);
    cursor: pointer;
    transition: all 0.2s;
    &:first-child {
      border-radius: 4px 0 0 4px;
    }
    &:last-child {
      border-radius: 0 4px 4px 0;
    }
    &.active {
      background: var(--m-accent-dim);
      color: var(--m-accent);
      border-color: var(--m-accent);
    }
    &:hover:not(.active) {
      color: var(--m-text);
      background: rgba(201, 169, 110, 0.06);
    }
  }
}
.direction-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  margin-bottom: 8px;
  position: relative;
  z-index: 1;
}
.toggle-btn {
  background: none;
  border: none;
  font-family: '寒蝉全圆体', var(--font-main);
  font-size: 9px;
  color: var(--m-muted);
  cursor: pointer;
  letter-spacing: 1px;
  padding: 3px 8px;
  border-radius: 6px;
  transition: all 0.2s;
  &.active {
    color: #fff;
    background: var(--m-accent);
    font-weight: 600;
  }
}
.toggle-track {
  width: 30px;
  height: 16px;
  background: rgba(139, 115, 85, 0.12);
  border-radius: 8px;
  cursor: pointer;
  position: relative;
}
.toggle-thumb {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--m-accent);
  position: absolute;
  top: 2px;
  left: 2px;
  transition: left 0.25s;
  &.toWorld {
    left: 16px;
  }
}
.btn-random {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  width: 100%;
  padding: 10px 0;
  margin-bottom: 6px;
  background: var(--m-accent-dim);
  border: 1px solid var(--m-accent);
  border-radius: 8px;
  cursor: pointer;
  position: relative;
  z-index: 1;
  color: var(--m-accent);
  font-family: '寒蝉全圆体', var(--font-main);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 3px;
  transition: all 0.2s;
  &:hover {
    background: var(--m-accent);
    color: #fff;
  }
}
.btn-icon {
  font-size: 10px;
}
.btn-custom-toggle {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  padding: 7px 0;
  background: none;
  border: 1px dashed var(--m-accent-dim);
  border-radius: 8px;
  cursor: pointer;
  color: var(--m-accent);
  font-family: '寒蝉全圆体', var(--font-main);
  font-size: 10px;
  letter-spacing: 2px;
  transition: all 0.2s;
  position: relative;
  z-index: 1;
  &:hover {
    border-color: var(--m-accent);
    border-style: solid;
  }
}
.custom-form {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin-top: 6px;
  padding: 10px;
  background: rgba(139, 115, 85, 0.04);
  border: 1px solid rgba(139, 115, 85, 0.1);
  border-radius: 8px;
}
.form-section {
  padding: 6px 8px;
  background: rgba(139, 115, 85, 0.06);
  border-radius: 6px;
  cursor: pointer;
  font-family: '寒蝉全圆体', var(--font-main);
  font-size: 10px;
  color: var(--m-muted);
  letter-spacing: 1px;
  transition: background 0.15s;
  user-select: none;
  &:hover {
    background: rgba(139, 115, 85, 0.12);
  }
}
.mx-arrow {
  display: inline-block;
  transition: transform 0.2s;
  font-size: 10px;
  margin-right: 2px;
  &.open {
    transform: rotate(90deg);
  }
}
.section-body {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding-top: 4px;
}
.mx-mode-toggle {
  font-size: 8px;
  color: var(--m-accent);
  cursor: pointer;
  background: var(--m-accent-dim);
  padding: 1px 6px;
  border-radius: 8px;
  margin-left: 4px;
  transition: all 0.15s;
  &:hover {
    background: var(--m-accent);
    color: #fff;
  }
}
.mx-fandom-simple {
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.mx-fandom-simple select,
.mx-fandom-simple input {
  padding: 5px 8px;
  border-radius: 6px;
  border: 1px solid rgba(139, 115, 85, 0.15);
  background: rgba(255, 255, 255, 0.6);
  color: #4a4035;
  font-family: 'DouyinSans', var(--font-main);
  font-size: 10px;
  outline: none;
  &:focus {
    border-color: var(--m-accent);
  }
}
.mx-fandom-ext {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 6px;
  background: rgba(139, 115, 85, 0.04);
  border: 1px solid rgba(139, 115, 85, 0.1);
  border-radius: 6px;
}
.mx-fandom-ext select,
.mx-fandom-ext input {
  padding: 5px 8px;
  border-radius: 6px;
  border: 1px solid rgba(139, 115, 85, 0.15);
  background: rgba(255, 255, 255, 0.6);
  color: var(--m-text);
  font-family: 'DouyinSans', var(--font-main);
  font-size: 10px;
  outline: none;
  &:focus {
    border-color: var(--m-accent);
  }
}
.tag-custom {
  border-style: dashed !important;
  display: inline-flex;
  align-items: center;
}
.tag-custom {
  display: inline-flex;
  align-items: center;
  gap: 1px;
}
.tag-pool .tag-custom input {
  width: 54px;
  height: 16px;
  line-height: 16px;
  border: none;
  background: transparent;
  font-family: inherit;
  font-size: 9px;
  color: var(--m-muted);
  outline: none;
  text-align: center;
  padding: 0;
  &::placeholder {
    color: var(--m-dim);
  }
}
.tag-custom-btn {
  width: 16px;
  height: 16px;
  border: none;
  border-radius: 50%;
  background: var(--m-accent-dim);
  color: var(--m-accent);
  font-size: 10px;
  line-height: 16px;
  cursor: pointer;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: all 0.12s;
  &:hover {
    background: var(--m-accent);
    color: #fff;
  }
}
.form-row {
  display: flex;
  flex-direction: column;
  gap: 3px;
  label {
    font-family: '寒蝉全圆体', var(--font-main);
    font-size: 9px;
    color: var(--m-muted);
    letter-spacing: 1px;
  }
  > select,
  > input,
  > textarea {
    padding: 5px 8px;
    border-radius: 6px;
    border: 1px solid rgba(139, 115, 85, 0.15);
    background: rgba(255, 255, 255, 0.6);
    color: #4a4035;
    font-family: 'DouyinSans', var(--font-main);
    font-size: 10px;
    outline: none;
    resize: vertical;
    &:focus {
      border-color: var(--m-accent);
    }
  }
}
.tag-pool {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}
.tag {
  padding: 2px 8px;
  border-radius: 10px;
  cursor: pointer;
  border: 1px solid var(--m-accent-dim);
  font-family: 'DouyinSans', var(--font-main);
  font-size: 9px;
  color: var(--m-muted);
  transition: all 0.12s;
  &:hover {
    border-color: var(--m-accent);
    color: var(--m-accent);
  }
  &.picked {
    background: var(--m-accent-dim);
    border-color: var(--m-accent);
    color: var(--m-accent);
    font-weight: 600;
  }
}
.btn-send {
  flex: 1;
  padding: 8px 0;
  background: var(--m-accent);
  border: none;
  border-radius: 8px;
  cursor: pointer;
  color: #fff;
  font-family: '寒蝉全圆体', var(--font-main);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 2px;
  transition: opacity 0.2s;
  &:hover {
    opacity: 0.85;
  }
}
.btn-gen {
  flex: 1.3;
  padding: 8px 0;
  background: var(--m-accent-dim);
  border: 1px solid var(--m-accent);
  border-radius: 8px;
  cursor: pointer;
  color: var(--m-accent);
  font-family: '寒蝉全圆体', var(--font-main);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 1px;
  transition: all 0.2s;
  &:hover:not(:disabled) {
    background: var(--m-accent);
    color: #fff;
  }
  &:disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }
}
.mx-other-input {
  padding: 5px 8px;
  border-radius: 6px;
  border: 1px solid rgba(139, 115, 85, 0.15);
  background: rgba(255, 255, 255, 0.6);
  color: #4a4035;
  font-family: 'DouyinSans', var(--font-main);
  font-size: 10px;
  outline: none;
  resize: vertical;
  min-height: 50px;
  &:focus {
    border-color: var(--m-accent);
  }
  &::placeholder {
    color: var(--m-dim);
  }
}
.mx-gen-row {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding: 2px 0;
}
.mx-save-toggle {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  cursor: pointer;
  user-select: none;
  input[type='checkbox'] {
    accent-color: var(--m-accent);
    width: 12px;
    height: 12px;
    cursor: pointer;
  }
  .toggle-label {
    font-family: '寒蝉全圆体', var(--font-main);
    font-size: 8px;
    color: var(--m-muted);
    letter-spacing: 1px;
    transition: color 0.15s;
  }
  &:hover .toggle-label {
    color: var(--m-accent);
  }
}
.btn-row {
  display: flex;
  gap: 6px;
  margin-top: 4px;
}
.mx-gen-status {
  text-align: center;
  padding: 8px;
  font-family: '寒蝉全圆体', var(--font-main);
  font-size: 10px;
  color: var(--m-muted);
  letter-spacing: 1px;
  &.error {
    color: var(--m-rose);
  }
}
.gen-spinner {
  display: inline-block;
  width: 12px;
  height: 12px;
  border: 2px solid var(--m-accent-dim);
  border-top-color: var(--m-accent);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
  margin-right: 6px;
  vertical-align: middle;
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
.mx-gen-result {
  margin-top: 6px;
  padding: 0;
  background: rgba(139, 115, 85, 0.06);
  border: 1px solid rgba(139, 115, 85, 0.12);
  border-radius: 8px;
  overflow: hidden;
}
.gen-result-label {
  font-family: '寒蝉全圆体', var(--font-main);
  font-size: 9px;
  color: var(--m-accent);
  letter-spacing: 2px;
  padding: 6px 8px;
  border-bottom: 1px solid rgba(139, 115, 85, 0.1);
}
.gen-result-text {
  display: block;
  width: 100%;
  min-height: 180px;
  max-height: 300px;
  overflow-y: auto;
  white-space: pre-wrap;
  font-family: 'DouyinSans', var(--font-main);
  font-size: 10px;
  color: var(--m-text);
  line-height: 1.7;
  padding: 8px;
  background: rgba(255, 255, 255, 0.3);
  border: 1px solid rgba(139, 115, 85, 0.12);
  border-radius: 6px;
  resize: vertical;
  outline: none;
  &:focus {
    border-color: var(--m-accent);
  }
}
.gen-result-actions {
  display: flex;
  gap: 6px;
  margin-top: 6px;
  padding: 0 4px 4px;
  align-items: center;
}
.btn-gen-save {
  padding: 5px 12px;
  background: var(--m-accent);
  border: none;
  border-radius: 6px;
  cursor: pointer;
  color: #fff;
  font-family: '寒蝉全圆体', var(--font-main);
  font-size: 9px;
  letter-spacing: 1px;
  transition: opacity 0.15s;
  &:hover {
    opacity: 0.85;
  }
}
.btn-gen-inject {
  padding: 5px 12px;
  background: none;
  border: 1px solid var(--m-accent);
  border-radius: 6px;
  cursor: pointer;
  color: var(--m-accent);
  font-family: '寒蝉全圆体', var(--font-main);
  font-size: 9px;
  letter-spacing: 1px;
  transition: all 0.15s;
  &:hover {
    background: var(--m-accent);
    color: #fff;
  }
}
.btn-gen-retry {
  padding: 5px 12px;
  background: none;
  border: 1px solid var(--m-accent-dim);
  border-radius: 6px;
  cursor: pointer;
  color: var(--m-muted);
  font-family: '寒蝉全圆体', var(--font-main);
  font-size: 9px;
  letter-spacing: 1px;
  transition: all 0.15s;
  &:hover {
    border-color: var(--m-accent);
    color: var(--m-accent);
  }
}
.gen-saved-hint {
  font-family: '寒蝉全圆体', var(--font-main);
  font-size: 9px;
  color: var(--m-accent);
  letter-spacing: 1px;
}
